import json, subprocess, hashlib
from datetime import datetime, timezone
from pathlib import Path
REPO = "/tmp/gddp-verify-131.U8QHZb/repo"
REC_SEP = "\x1e"; END_SEP = "\x1f"
COMMIT_FMT = REC_SEP.join(["%H","%P","%at","%ct","%aN","%cN"]) + REC_SEP + "%B" + END_SEP
def git(*args):
    r = subprocess.run(["git", *args], cwd=REPO, capture_output=True, text=True)
    return r.stdout
def iso_utc(unix):
    return datetime.fromtimestamp(int(unix), tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
def build(extra_cfg):
    head = git(*extra_cfg, "rev-parse","HEAD").strip()
    total = int(git(*extra_cfg, "rev-list","--count","HEAD").strip())
    meta_raw = git(*extra_cfg, "log","--reverse","--topo-order","--format="+COMMIT_FMT)
    entries=[]; by_sha={}
    for rec in meta_raw.split(END_SEP):
        rec = rec.strip("\n")
        if not rec.strip(): continue
        sha,parents,at,ct,an,cn,body = rec.split(REC_SEP)
        e = {"commit":sha,"parents":parents.split() if parents else [],"authored_at":iso_utc(at),"committed_at":iso_utc(ct),"author":an,"committer":cn,"message":body.strip("\n"),"files":[]}
        entries.append(e); by_sha[sha]=e
    raw = git(*extra_cfg, "log","--reverse","--topo-order","--numstat","--format=%H")
    current=None
    for line in raw.splitlines():
        if not line.strip(): continue
        if len(line)==40 and all(c in "0123456789abcdef" for c in line):
            current=by_sha[line]
        elif current is not None:
            parts=line.split("\t")
            if len(parts)==3:
                added,deleted,path=parts
                current["files"].append({"path":path,"status":"binary" if added=="-" else "text","lines_added":None if added=="-" else int(added),"lines_deleted":None if deleted=="-" else int(deleted)})
    out_lines=[json.dumps({"manifest":"part2/layers/git/git-export.jsonl","generated_by":"build_git_export.py","repo":"skchaudr/MyAPI","head_commit":head,"commit_count":total,"scope":"full history, topo-order oldest-first","date_convention":"all dates absolute ISO-8601 UTC"},sort_keys=True)]
    for e in entries: out_lines.append(json.dumps(e,sort_keys=True))
    return ("\n".join(out_lines)+"\n").encode("utf-8")

committed = Path("/Users/sab-mini/repos/MyAPI/part2/layers/git/git-export.jsonl").read_bytes()
print("committed sha256:", hashlib.sha256(committed).hexdigest())
for label, cfg in [("default(myers)", []), ("histogram", ["-c","diff.algorithm=histogram"]), ("patience", ["-c","diff.algorithm=patience"])]:
    b = build(cfg)
    print(label, "sha256:", hashlib.sha256(b).hexdigest(), "byte-identical:", b == committed)
